function findPlace(text) {
  const t = String(text || '').toLowerCase();
  for (const c of GEO_KEYS) if (new RegExp(`\\b${c}\\b`).test(t)) return GEO[c];
  // koi bhi desh (Italy, Spain, Kenya...): LinkedIn "Milan, Lombardy, Italy" -> ['Milan', 'Lombardy', 'Italy']
  const parts = String(text || '').split(',').map(x => x.trim()).filter(Boolean);
  const last = (parts[parts.length - 1] || '').toLowerCase().replace(/^the /, '');
  const co = COUNTRY.find(([rx]) => rx.test(t));
  const name = co ? co[1] : WORLD.find(w => w.toLowerCase() === last);
  if (!name) return null;
  let city = parts.length > 1 ? parts[0].replace(/\s*(metropolitan|metro) (area|region)$/i, '').replace(/^greater\s+/i, '').replace(/\s+area$/i, '') : '';
  if (city.toLowerCase() === name.toLowerCase() || city.length > 40) city = '';
  return [city, city && parts.length > 2 ? parts[1] : '', name];
